    for(const note of reportCreditNotes)rows.push(['Credit note',note.date,note.number,note.customerName,note.lines.map(line=>line.productName).join(', '),note.lines.reduce((sum,line)=>sum+line.qty,0),undefined,undefined,-note.total,undefined,undefined,`Invoice ${note.sourceInvoiceId||''}`]);
    for(const expense of reportExpenses)rows.push(['Expense',expense.date,String(expense.id),'',expense.category?`${expense.title} (${expense.category})`:expense.title,undefined,undefined,undefined,expense.amount,undefined,undefined,expense.recurringExpenseId?'Recurring':'']);
