    for(const cash of reportCashMovements)rows.push(['Cash',cash.date,cash.id,'',cash.note,undefined,undefined,undefined,(cash.kind==='cash_out'||cash.kind==='expense'||cash.kind==='supplier_payment'?-1:1)*cash.amountCentimes/100,undefined,undefined,cash.kind]);
    for(const entry of reportBankEntries)rows.push(['Bank',entry.date,entry.reference||entry.id,'',entry.description,undefined,undefined,undefined,(entry.direction==='in'?1:-1)*entry.amountCentimes/100,undefined,undefined,entry.matchedSourceId?'Reconciled':'Open']);
    for(const movement of reportStockMovements){const product=products.find(item=>String(item.id)===movement.productId);const warehouse=warehouses.find(item=>item.id===movement.warehouseId);rows.push(['Stock',movement.createdAt.slice(0,10),movement.reference||'',warehouse?.name||'',product?.name||movement.productId,movement.quantity,movement.unitCost||0,undefined,undefined,undefined,undefined,movement.kind]);}
    for(const balance of customerBalances.filter(item=>item.outstandingCentimes>0))rows.push(['Receivable','', '',balance.customerName,'Open invoices',undefined,undefined,undefined,undefined,undefined,balance.outstandingCentimes/100,'Open']);
    for(const supplier of suppliers){const total=Math.round((purchases.filter(item=>item.supplierId?item.supplierId===String(supplier.id):item.supplierName===supplier.name).reduce((sum,item)=>sum+item.total,0)+purchaseDocuments.filter(doc=>doc.kind==='supplier_invoice'&&doc.status==='confirmed'&&doc.supplierId===String(supplier.id)).reduce((sum,doc)=>sum+purchaseTotals(doc).total,0))*100);const credits=supplierReturnTotalCentimes(supplierReturns,String(supplier.id),supplier.name)+purchaseCreditCentimes(purchaseDocuments,String(supplier.id));const balance=supplierOutstanding(total,supplierPayments,String(supplier.id),credits);const supplierCredit=supplierCreditBalance(total,supplierPayments,String(supplier.id),credits);const paid=supplierPayments.filter(item=>item.supplierId===String(supplier.id)).reduce((sum,item)=>sum+item.amount,0);if(balance>0)rows.push(['Payable','', '',supplier.name,'Supplier balance',undefined,undefined,undefined,total/100,paid/100,balance/100,'Open']);if(supplierCredit>0)rows.push(['Supplier credit','', '',supplier.name,'Supplier credit balance',undefined,undefined,undefined,undefined,undefined,supplierCredit/100,'Credit']);}
    for(const log of reportWorkLogs){const task=tasks.find(item=>item.id===log.taskId);rows.push(['Work log',log.date,log.id,log.technician,task?.title||log.taskId,log.durationMinutes,undefined,log.hourlyRateCentimes/100,workLogCostCentimes(log)/100,undefined,undefined,'']);}
    for(const request of reportInstallationRequests)rows.push(['Installation request',request.requestedDate,request.id,customers.find(customer=>customer.id===request.customerId)?.name||'',request.type,undefined,undefined,undefined,undefined,undefined,undefined,request.status]);
