  const addCustomer=()=>{const opening=Number(customerOpeningBalance.replace(',','.'));const credit=Number(customerCreditLimit.replace(',','.'));const terms=Number(customerPaymentTerms);if(!customer.trim()||!Number.isFinite(opening)||opening<0||!Number.isFinite(credit)||credit<0||!Number.isSafeInteger(terms)||terms<0){Alert.alert(tr('معلومات ناقصة'),tr('راجع اسم الزبون والأرصدة وشروط الأداء.'));return;}if(customers.some(item=>item.id!==editingCustomerId&&item.name.trim().toLowerCase()===customer.trim().toLowerCase())){Alert.alert(tr('اسم الزبون مستعمل'),tr('كل زبون خاصو اسم مختلف باش الحساب وكشف الحساب يبقاو مربوطين به.'));return;}const updated={id:editingCustomerId||Date.now(),name:customer.trim(),phone:customerPhone.trim(),address:customerAddress.trim(),ice:customerIce.trim(),openingBalanceCentimes:Math.round(opening*100),creditLimitCentimes:Math.round(credit*100),paymentTermsDays:terms};if(editingCustomerId){const previous=customers.find(item=>item.id===editingCustomerId);setCustomers(current=>current.map(item=>item.id===editingCustomerId?updated:item));if(previous&&previous.name!==updated.name){setSales(current=>current.map(item=>item.customerName===previous.name?{...item,customerName:updated.name}:item));setQuotes(current=>current.map(item=>item.customerName===previous.name?{...item,customerName:updated.name}:item));setDocuments(current=>current.map(item=>item.customerName===previous.name?{...item,customerName:updated.name}:item));setPayments(current=>current.map(item=>item.customerName===previous.name?{...item,customerName:updated.name}:item));setProjects(current=>current.map(item=>item.customerName===previous.name?{...item,customerName:updated.name}:item));}}else setCustomers(current=>[updated,...current]);clearCustomerForm();};
