  const addSupplier=()=>{if(!supplierName.trim()){Alert.alert(tr('معلومات ناقصة'),tr('دخل اسم المورد.'));return;}if(suppliers.some(item=>item.id!==editingSupplierId&&item.name.trim().toLowerCase()===supplierName.trim().toLowerCase())){Alert.alert(tr('اسم المورد مستعمل'),tr('كل مورد خاصو اسم مختلف باش الحساب يبقى مربوط به.'));return;}const updated={id:editingSupplierId||Date.now(),name:supplierName.trim(),phone:supplierPhone.trim(),address:supplierAddress.trim(),ice:supplierIce.trim()};if(editingSupplierId){const previous=suppliers.find(item=>item.id===editingSupplierId);setSuppliers(current=>current.map(item=>item.id===editingSupplierId?updated:item));if(previous&&previous.name!==updated.name){setPurchases(current=>current.map(item=>item.supplierName===previous.name?{...item,supplierName:updated.name}:item));setSupplierReturns(current=>current.map(item=>item.supplierName===previous.name?{...item,supplierName:updated.name}:item));}}else setSuppliers(current=>[updated,...current]);clearSupplierForm();};
  const addPurchase=()=>{const p=products.find(x=>String(x.id)===purchaseProduct);const sup=suppliers.find(x=>String(x.id)===purchaseSupplier);const q=Number(purchaseQty),cost=Number(purchaseCost.replace(',','.'));if(!p||!sup||!Number.isInteger(q)||q<1||!Number.isFinite(cost)||cost<0){Alert.alert(tr('معلومات ناقصة'),tr('اختار المنتج والمورد ودخل الكمية وثمن الشراء.'));return;}const item:Purchase={id:Date.now(),productId:p.id,supplierId:String(sup.id),productName:p.name,supplierName:sup.name,qty:q,unitCost:cost,total:q*cost,date:new Date().toLocaleDateString('fr-MA')};setPurchases(v=>[item,...v]);setProducts(v=>v.map(x=>x.id===p.id?{...x,qty:x.qty+q}:x));setStockMovements(v=>[...v,{id:'purchase-'+item.id,productId:String(p.id),warehouseId:activeWarehouseId,kind:'purchase',quantity:q,unitCost:cost,createdAt:new Date().toISOString(),reference:String(item.id),note:'شراء من المورد '+sup.name}]);setPurchaseQty('1');setPurchaseCost('');Alert.alert(tr('تم تسجيل الشراء'),`المجموع: ${item.total.toFixed(2)} DH`);};
  const createPurchaseDoc=(input:{kind:'request'|'order';supplierId:string;warehouseId:string;lines:PurchaseLine[];globalDiscount:number})=>{try{const supplier=suppliers.find(item=>String(item.id)===input.supplierId);if(!supplier)throw new Error('خاص اختيار المورد');if(input.kind==='order'&&!warehouses.some(item=>item.id===input.warehouseId&&item.active))throw new Error('اختار المخزن المستهدف');const id='pd-'+Date.now();const doc=createPurchaseDocument({id,number:(input.kind==='order'?'CMD-':'DDA-')+Date.now(),kind:input.kind,supplierId:input.supplierId,...(input.kind==='order'?{warehouseId:input.warehouseId}:{}),lines:input.lines,globalDiscount:input.globalDiscount,createdAt:new Date().toISOString()},purchaseDocuments);setPurchaseDocuments(current=>[doc,...current]);Alert.alert(tr('تم حفظ وثيقة الشراء'),doc.number);}catch(error){Alert.alert(tr('تعذر حفظ وثيقة الشراء'),error instanceof Error?tr(error.message):tr('راجع البيانات وحاول من جديد.'));}};
  const returnFromSupplierInvoice=(invoice:PurchaseDocument,quantities:Record<string,number>)=>{try{const credit=createSupplierCredit(invoice,purchaseDocuments,quantities,'pcredit-'+Date.now(),'AV-ACH-'+Date.now(),new Date().toISOString());const warehouseId=invoice.warehouseId;if(!warehouseId||!warehouses.some(item=>item.id===warehouseId&&item.active))throw new Error('اختار المخزن المستهدف');for(const line of credit.lines){const available=warehouseStock(stockMovements,line.productId,warehouseId);if(line.quantity>available)throw new Error('الكمية أكبر من مخزون المخزن المحدد');if(!products.some(product=>String(product.id)===line.productId))throw new Error('المنتج غير موجود فالمخزون');}setProducts(current=>current.map(product=>{const quantity=credit.lines.filter(line=>line.productId===String(product.id)).reduce((sum,line)=>sum+line.quantity,0);return quantity?{...product,qty:product.qty-quantity}:product;}));setStockMovements(current=>[...current,...credit.lines.map((line,index)=>({id:'supplier-credit-'+credit.id+'-'+index,productId:line.productId,warehouseId,kind:'return_out' as const,quantity:line.quantity,unitCost:line.unitCost,createdAt:new Date().toISOString(),reference:credit.number,note:'إرجاع مرتبط بفاتورة المورد '+invoice.number}))]);setPurchaseDocuments(current=>[credit,...current]);Alert.alert(tr('تم إرجاع المنتجات للمورد'),`${credit.number} · ${purchaseTotals(credit).total.toFixed(2)} DH`);}catch(error){Alert.alert(tr('تعذر إرجاع المنتجات'),error instanceof Error?tr(error.message):tr('راجع الكميات.'));}};
  const updatePurchaseDocStatus=(doc:PurchaseDocument,status:'confirmed'|'cancelled')=>{try{const updated=changePurchaseStatus(doc,status);setPurchaseDocuments(current=>current.map(item=>item.id===doc.id?updated:item));Alert.alert(tr('تم تحديث الوثيقة'),updated.number);}catch(error){Alert.alert(tr('تعذر تحديث الوثيقة'),error instanceof Error?tr(error.message):tr('راجع البيانات وحاول من جديد.'));}};
  const convertPurchaseDoc=(source:PurchaseDocument,target:'order'|'receipt'|'supplier_invoice')=>{try{const id='pd-'+Date.now();const prefix=target==='order'?'CMD-':target==='receipt'?'REC-':'FAC-ACH-';const converted=convertPurchaseDocument(source,target,purchaseDocuments,id,prefix+Date.now(),new Date().toISOString(),activeWarehouseId);if(target==='receipt'){if(!warehouses.some(item=>item.id===converted.warehouseId&&item.active))throw new Error('اختار المخزن المستهدف');const missing=converted.lines.find(line=>!products.some(product=>String(product.id)===line.productId));if(missing)throw new Error('المنتج غير موجود فالمخزون');setProducts(current=>current.map(product=>{const quantity=converted.lines.filter(line=>line.productId===String(product.id)).reduce((sum,line)=>sum+line.quantity,0);return quantity?{...product,qty:product.qty+quantity}:product;}));setStockMovements(current=>[...current,...converted.lines.map((line,index)=>({id:'purchase-receipt-'+converted.id+'-'+index,productId:line.productId,warehouseId:converted.warehouseId||activeWarehouseId,kind:'purchase' as const,quantity:line.quantity,unitCost:line.unitCost,createdAt:new Date().toISOString(),reference:converted.number,note:'استلام أمر شراء '+source.number}))]);}setPurchaseDocuments(current=>[converted,...current]);Alert.alert(tr(target==='receipt'?'تم الاستلام وتحديث المخزون':'تم إنشاء الوثيقة'),converted.number);}catch(error){Alert.alert(tr('تعذر تحويل وثيقة الشراء'),error instanceof Error?tr(error.message):tr('راجع البيانات وحاول من جديد.'));}};
  const addSupplierReturn=()=>{try{const purchase=purchases.find(item=>String(item.id)===supplierReturnPurchase);if(!purchase)throw new Error('اختار الشراء اللي بغيتي ترجع منو.');const product=products.find(item=>item.id===purchase.productId)||products.find(item=>item.name===purchase.productName);if(!product)throw new Error('المنتج الأصلي غير مربوط بالشراء');const result=createSupplierReturn({...purchase,productId:product.id},supplierReturns,Number(supplierReturnQuantity.replace(',','.')),warehouseStock(stockMovements,String(product.id),activeWarehouseId),Date.now(),new Date().toISOString().slice(0,10));setSupplierReturns(current=>[result,...current]);setProducts(current=>current.map(item=>item.id===product.id?{...item,qty:item.qty-result.quantity}:item));setStockMovements(current=>[...current,{id:'supplier-return-'+result.id,productId:String(product.id),warehouseId:activeWarehouseId,kind:'return_out',quantity:result.quantity,unitCost:result.unitCost,createdAt:new Date().toISOString(),reference:String(result.id),note:'إرجاع للمورد '+result.supplierName}]);setSupplierReturnQuantity('1');Alert.alert(tr('تم إرجاع المنتجات للمورد'),`${result.total.toFixed(2)} DH`);}catch(error){Alert.alert(tr('تعذر إرجاع المنتجات'),error instanceof Error?tr(error.message):tr('راجع البيانات وحاول من جديد.'));}};
  const addSupplierPayment=()=>{const amount=Number(supplierPaymentAmount.replace(',','.'));const supplier=suppliers.find(x=>String(x.id)===supplierPaymentSupplier);const payment:SupplierPayment={id:String(Date.now()),supplierId:supplierPaymentSupplier,amount:Math.round(amount*100),date:new Date().toISOString().slice(0,10),method:supplierPaymentMethod,...(supplierPaymentReference.trim()?{reference:supplierPaymentReference.trim()}:{})};const errors=validateSupplierPayment(payment);if(!supplier||errors.length){Alert.alert(tr('معلومات ناقصة'),tr(errors[0]||'اختار المورد.'));return;}const invoiceTotal=Math.round((purchases.filter(x=>x.supplierId?x.supplierId===String(supplier.id):x.supplierName===supplier.name).reduce((sum,x)=>sum+x.total,0)+purchaseDocuments.filter(doc=>doc.kind==='supplier_invoice'&&doc.status==='confirmed'&&doc.supplierId===String(supplier.id)).reduce((sum,doc)=>sum+purchaseTotals(doc).total,0))*100);const credits=supplierReturnTotalCentimes(supplierReturns,supplierPaymentSupplier,supplier.name)+purchaseCreditCentimes(purchaseDocuments,supplierPaymentSupplier);const balance=supplierOutstanding(invoiceTotal,supplierPayments,supplierPaymentSupplier,credits);if(payment.amount>balance){Alert.alert(tr('المبلغ أكبر من الدين'),`${tr('المبلغ المتبقي للمورد:')} ${(balance/100).toFixed(2)} DH`);return;}if(payment.method==='cash'){try{setCashMovements(postCashMovement({id:'supplier-cash-'+payment.id,kind:'supplier_payment',amountCentimes:payment.amount,date:payment.date,note:supplier.name},cashMovements));}catch(error){Alert.alert(tr('تعذر تسجيل حركة الصندوق'),error instanceof Error?tr(error.message):tr('الرصيد النقدي غير كافٍ'));return;}}setSupplierPayments(v=>[payment,...v]);setSupplierPaymentAmount('');setSupplierPaymentReference('');Alert.alert(tr('تم تسجيل الأداء'),tr('تحدّث رصيد المورد.'));};
  const addExpense=()=>{const a=Number(expenseAmount.replace(',','.'));if(!expenseTitle.trim()||!Number.isFinite(a)||a<=0){Alert.alert(tr('معلومات ناقصة'),tr('دخل وصف المصروف ومبلغ صحيح.'));return;}if(expensePaidBy==='cash'){try{setCashMovements(postCashMovement({id:'expense-cash-'+Date.now(),kind:'expense',amountCentimes:Math.round(a*100),date:new Date().toISOString().slice(0,10),note:expenseTitle.trim()},cashMovements));}catch(error){Alert.alert(tr('تعذر تسجيل المصروف'),error instanceof Error?tr(error.message):tr('الرصيد النقدي غير كافٍ'));return;}}setExpenses(v=>[{id:Date.now(),title:expenseTitle.trim(),amount:a,date:new Date().toISOString().slice(0,10),category:expenseCategory.trim()||undefined},...v]);setExpenseTitle('');setExpenseAmount('');};
  const addRecurringExpense=()=>{const amount=Number(expenseAmount.replace(',','.'));const item:RecurringExpense={id:'expense-rule-'+Date.now(),title:expenseTitle.trim(),amount,category:expenseCategory.trim(),interval:recurringInterval,nextDueDate:new Date().toISOString().slice(0,10),anchorDay:new Date().getUTCDate(),active:true};const errors=validateRecurringExpense(item);if(errors.length){Alert.alert(tr('معلومات ناقصة'),tr(errors[0]));return;}setRecurringExpenses(current=>[item,...current]);Alert.alert(tr('تمت إضافة المصروف المتكرر'),tr('المصروف المتكرر سيبدأ من تاريخ اليوم.'));};
  const generateRecurring=()=>{try{const result=generateDueExpenses(recurringExpenses,expenses,new Date().toISOString().slice(0,10));setRecurringExpenses(result.schedules);setExpenses(result.expenses);Alert.alert(tr('توليد المصاريف المستحقة'),result.createdCount?`${result.createdCount} — ${tr('تسجلات المصاريف المتكررة المستحقة.')}`:tr('ما كاين حتى مصروف متكرر مستحق دابا.'));}catch(error){Alert.alert(tr('تعذر توليد المصاريف'),error instanceof Error?tr(error.message):tr('راجع البيانات وحاول من جديد.'));}};
  const addBankEntries=(incoming:BankEntry[])=>{try{for(const entry of incoming){const errors=validateBankEntry(entry,[...bankEntries,...incoming.filter(item=>item!==entry)]);if(errors.length)throw new Error(errors[0]);}setBankEntries(current=>[...incoming,...current]);Alert.alert(tr('تم استيراد حركات البنك'),String(incoming.length));}catch(error){Alert.alert(tr('تعذر استيراد كشف البنك'),error instanceof Error?tr(error.message):tr('راجع تنسيق كشف البنك.'));}};
  const reconcileBank=(entry:BankEntry,source:BankSource)=>{try{const updated=reconcileBankEntry(entry,source,bankEntries,bankSources);setBankEntries(current=>current.map(item=>item.id===entry.id?updated:item));Alert.alert(tr('تمت المطابقة'),source.label);}catch(error){Alert.alert(tr('تعذر إجراء المطابقة'),error instanceof Error?tr(error.message):tr('راجع الحركة البنكية وحاول من جديد.'));}};
  const addCashMovement=()=>{try{const amount=Number(cashAmount.replace(',','.'));const entry:CashMovement={id:'cash-'+Date.now(),kind:cashKind,amountCentimes:Math.round(amount*100),date:new Date().toISOString().slice(0,10),note:cashNote.trim()};setCashMovements(postCashMovement(entry,cashMovements));setCashAmount('');setCashNote('');Alert.alert(tr('تم تسجيل حركة الصندوق'),tr('تحدّث رصيد الصندوق.'));}catch(error){Alert.alert(tr('تعذر تسجيل الحركة'),error instanceof Error?tr(error.message):tr('راجع المبلغ ورصيد الصندوق.'));}};
  const addQuote=()=>{const p=products.find(x=>String(x.id)===quoteProduct);const c=customers.find(x=>String(x.id)===quoteCustomer);const q=Number(quoteQty);if(!p||!c||!Number.isInteger(q)||q<1){Alert.alert(tr('معلومات ناقصة'),tr('اختار المنتج والزبون والكمية.'));return;}const x:Quote={id:Date.now(),productName:p.name,customerName:c.name,qty:q,unitPrice:p.price,total:q*p.price,date:new Date().toLocaleDateString('fr-MA'),status:'معلق'};setQuotes(v=>[x,...v]);setQuoteQty('1');Alert.alert(tr('تم حفظ عرض السعر'),`${x.total.toFixed(2)} DH`);};
  const convertQuote=(quote:Quote,type:QuoteConversionType,requestedDeliveryLines?:DeliveryRequestLine[])=>{
    try{
      const existingForQuote=documents.filter(document=>document.type!=='credit_note').map(document=>({sourceQuoteId:document.sourceQuoteId,type:document.type as DocumentKind,total:document.total,lines:document.lines}));
      if(type==='delivery'){
        const previous=existingForQuote.filter(document=>document.sourceQuoteId===quote.id&&document.type==='delivery');
        const remaining=remainingDeliveryLines(quote.lines||[],previous).filter(line=>line.remainingQty>0);
        const requested=requestedDeliveryLines||remaining.map(line=>({productId:line.productId,qty:line.remainingQty}));
        const requestedByProduct=new Map<number,number>();
        requested.forEach(line=>requestedByProduct.set(line.productId,(requestedByProduct.get(line.productId)||0)+line.qty));
        const insufficient=Array.from(requestedByProduct.entries()).find(([productId,quantity])=>{
          const product=products.find(p=>p.id===productId);
          return !product||quantity>warehouseStock(stockMovements,String(productId),activeWarehouseId);
        });
        if(insufficient)throw new Error('الكمية المطلوبة أكبر من مخزون المستودع المحدد.');
      }
      const result=createConvertedDocument(
        quote,type,existingForQuote,products,Date.now(),new Date().toLocaleDateString('fr-MA'),requestedDeliveryLines,
      );
      if(type==='invoice'){
        const account=customers.find(customer=>customer.name===quote.customerName);
        const limit=account?.creditLimitCentimes||0;
        const currentOutstanding=balanceFor(quote.customerName)?.outstandingCentimes||0;
        if(limit>0&&currentOutstanding+Math.round(result.document.total*100)>limit)throw new Error('فاتورة الزبون غادي تفوت سقف الدين المحدد.');
      }
      const invoiceCustomer=customers.find(customer=>customer.name===quote.customerName);
      const terms=invoiceCustomer?.paymentTermsDays||0;
      const dueDate=new Date(new Date().toISOString().slice(0,10)+'T00:00:00.000Z');dueDate.setUTCDate(dueDate.getUTCDate()+terms);
      const convertedDocument:CommercialDocument={...result.document,...(type==='invoice'&&terms>0?{dueDate:dueDate.toISOString().slice(0,10)}:{})};
      setDocuments(current=>[convertedDocument,...current]);
      if(type==='delivery'){setProducts(result.updatedProducts as Product[]);const delivery=result.document;setStockMovements(v=>[...v,...delivery.lines.map((line,index)=>({id:'delivery-'+delivery.id+'-'+index,productId:String(line.productId),warehouseId:activeWarehouseId,kind:'sale' as const,quantity:line.qty,createdAt:new Date().toISOString(),reference:delivery.number,note:'سند خروج'}))]);}
      Alert.alert(tr('تم التحويل'),type==='invoice'?'تسجلات الفاتورة.':'تسجل سند الخروج وتحدّث المخزون.');
    }catch(error){
      Alert.alert(tr('تعذر التحويل'),error instanceof Error?error.message:'وقع خطأ أثناء تحويل العرض.');
    }
  };
  const addPayment=()=>{
    const c=customers.find(x=>String(x.id)===paymentCustomer);
    const a=Number(paymentAmount.replace(',','.'));
    if(!c||!Number.isFinite(a)||a<=0){Alert.alert(tr('معلومات ناقصة'),tr('اختار الزبون ودخل مبلغ صحيح.'));return;}
    const invoice=documents.find(d=>d.id===Number(paymentDocument)&&d.type==='invoice'&&d.customerName===c.name);
    if(paymentDocument&&!invoice){Alert.alert(tr('الفاتورة غير موجودة'),tr('عاود اختار فاتورة صالحة لهذا الزبون.'));return;}
    let updatedInvoice:ReturnType<typeof applyPaymentToInvoice>['invoice']|undefined;
    if(invoice){
      try{updatedInvoice=applyPaymentToInvoice({type:'invoice',total:invoice.total,paidCentimes:invoice.paidCentimes,creditedCentimes:invoice.creditedCentimes,status:invoice.status},Math.round(a*100)).invoice;}
      catch(error){Alert.alert(tr('تعذر تسجيل الأداء'),error instanceof Error?error.message:'راجع مبلغ الأداء.');return;}
    }
    if(paymentMethod==='نقداً'){try{setCashMovements(postCashMovement({id:'customer-cash-'+Date.now(),kind:'customer_payment',amountCentimes:Math.round(a*100),date:new Date().toISOString().slice(0,10),note:c.name},cashMovements));}catch(error){Alert.alert(tr('تعذر تسجيل حركة الصندوق'),error instanceof Error?tr(error.message):tr('راجع رصيد الصندوق.'));return;}}
    if(invoice&&updatedInvoice)setDocuments(current=>current.map(d=>d.id===invoice.id?{...d,paidCentimes:updatedInvoice!.paidCentimes,status:updatedInvoice!.status}:d));
    setPayments(v=>[{id:Date.now(),customerName:c.name,amount:a,method:paymentMethod,date:new Date().toLocaleDateString('fr-MA'),note:paymentNote.trim(),...(invoice?{documentId:invoice.id}:{})},...v]);
    setPaymentAmount('');setPaymentNote('');setPaymentDocument('');
    Alert.alert(tr('تم تسجيل الأداء'),invoice?'تحدّث الرصيد المتبقي ديال الفاتورة.':'تسجل الأداء كدفعة غير مخصصة لفاتورة.');
  };
  const updateTrackedSalesDocument=(doc:CommercialDocument,next:string)=>{try{if(doc.type!=='customer_order'&&doc.type!=='proforma')throw new Error('نوع الوثيقة غير مدعوم');const orderQuote=quotes.find(item=>item.id===doc.sourceQuoteId);const deliveries=documents.filter(item=>item.type==='delivery'&&item.sourceQuoteId===doc.sourceQuoteId).map(item=>({sourceQuoteId:item.sourceQuoteId,type:'delivery' as const,total:item.total,lines:item.lines}));const hasDelivery=deliveries.length>0&&(!orderQuote?.lines?.length||remainingDeliveryLines(orderQuote.lines,deliveries).every(line=>line.remainingQty<=0));const updated=changeTrackedSalesDocumentStatus({type:doc.type as 'customer_order'|'proforma',status:doc.status,sourceQuoteId:doc.sourceQuoteId},next,hasDelivery);setDocuments(current=>current.map(item=>item.id===doc.id?{...item,status:updated.status}:item));Alert.alert(tr('تم تحديث الوثيقة'),tr(updated.status));}catch(error){Alert.alert(tr('تعذر تحديث الوثيقة'),error instanceof Error?tr(error.message):tr('راجع الحالة وحاول من جديد.'));}};
  const addCreditNote=(creditInvoice:CreditInvoice,quantities:Record<string,number>)=>{
    const currentNotes=documents.filter(document=>document.type==='credit_note') as CreditNote[];
    const result=createCreditNote(creditInvoice,currentNotes,products,quantities,Date.now(),new Date().toLocaleDateString('fr-MA'));
    const appliedCentimes=(creditInvoice.paidCentimes||0)+result.creditedCentimes;
    const nextStatus=appliedCentimes>=Math.round(creditInvoice.total*100)?'paid':appliedCentimes>0?'partially_paid':creditInvoice.status;
    setDocuments(current=>[result.note,...current.map(document=>document.id===creditInvoice.id?{...document,creditedCentimes:result.creditedCentimes,status:nextStatus}:document)]);
    setProducts(result.updatedProducts as Product[]);
    setStockMovements(current=>[...current,...result.note.lines.map((line,index)=>({id:'return-in-'+result.note.id+'-'+index,productId:String(line.productId),warehouseId:activeWarehouseId,kind:'return_in' as const,quantity:line.qty,unitCost:products.find(product=>product.id===line.productId)?.costPrice||0,createdAt:new Date().toISOString(),reference:result.note.number,note:'إرجاع من الزبون بسند '+result.note.number}))]);
    Alert.alert(tr('تم إنشاء الأفوار'),tr('تسجل الإرجاع وزاد للمخزون.'));
  };
  const exportBackup=async()=>{try{setBackupBusy(true);const json=await createBackup({language,companyProfile,products,stockMovements,warehouses,activeWarehouseId,customers,sales,posReturns,cashMovements,parkedPosSales,purchases,purchaseDocuments,supplierReturns,expenses,recurringExpenses,suppliers,quotes,payments,documents,projects,tasks,workLogs,workLogSettlements,installationRequests,technicians,equipment,bankEntries,supplierPayments});await Share.share({title:'HamZa backup',message:json});}catch(e){Alert.alert(tr('خطأ'),tr('ما قدرناش نوجدوا النسخة الاحتياطية.'));}finally{setBackupBusy(false);}};
  const importBackup=()=>{Alert.alert(tr('استرجاع البيانات'),tr('هاد العملية غادي تعوض البيانات الحالية بالنسخة اللي لصقتي. واش متأكد؟'),[{text:tr('إلغاء'),style:'cancel'},{text:tr('استرجاع البيانات'),style:'destructive',onPress:async()=>{try{setBackupBusy(true);const d=await restoreBackup(backupText);setLanguage(d.language==='FR'?'FR':'AR');setCompanyProfile(normalizeCompanyProfile(d.companyProfile));setWarehouses(normalizeWarehouses(d.warehouses));setActiveWarehouseId(typeof d.activeWarehouseId==='string'&&normalizeWarehouses(d.warehouses).some(w=>w.id===d.activeWarehouseId)?d.activeWarehouseId:'main');setProducts(Array.isArray(d.products)?d.products as Product[]:[]);setStockMovements(Array.isArray(d.stockMovements)?d.stockMovements as StockMovement[]:(Array.isArray(d.products)?(d.products as Product[]).filter(p=>p.qty>0).map(p=>({id:'opening-backup-'+p.id,productId:String(p.id),warehouseId:'main',kind:'opening' as const,quantity:p.qty,unitCost:p.costPrice||0,createdAt:new Date().toISOString(),note:'رصيد افتتاحي مرحّل من النسخة الاحتياطية'})):[]));setCustomers(Array.isArray(d.customers)?d.customers as Customer[]:[]);setSales(Array.isArray(d.sales)?d.sales as Sale[]:[]);setPosReturns(Array.isArray(d.posReturns)?d.posReturns as PosReturn[]:[]);setCashMovements(Array.isArray(d.cashMovements)?d.cashMovements as CashMovement[]:[]);setParkedPosSales(Array.isArray(d.parkedPosSales)?d.parkedPosSales as ParkedPosSale[]:[]);setPurchases(Array.isArray(d.purchases)?d.purchases as Purchase[]:[]);setPurchaseDocuments(Array.isArray(d.purchaseDocuments)?d.purchaseDocuments as PurchaseDocument[]:[]);setSupplierReturns(Array.isArray(d.supplierReturns)?d.supplierReturns as SupplierReturn[]:[]);setExpenses(Array.isArray(d.expenses)?d.expenses as Expense[]:[]);setRecurringExpenses(Array.isArray(d.recurringExpenses)?d.recurringExpenses as RecurringExpense[]:[]);setSuppliers(Array.isArray(d.suppliers)?d.suppliers as Supplier[]:[]);setSupplierPayments(Array.isArray(d.supplierPayments)?d.supplierPayments as SupplierPayment[]:[]);setQuotes(Array.isArray(d.quotes)?d.quotes as Quote[]:[]);setPayments(Array.isArray(d.payments)?d.payments as Payment[]:[]);setDocuments(Array.isArray(d.documents)?d.documents as CommercialDocument[]:[]);setProjects(Array.isArray(d.projects)?d.projects as ProjectRecord[]:[]);setTasks(Array.isArray(d.tasks)?d.tasks as AgendaTask[]:[]);setWorkLogs(Array.isArray(d.workLogs)?d.workLogs as WorkLog[]:[]);setWorkLogSettlements(Array.isArray(d.workLogSettlements)?d.workLogSettlements as WorkLogSettlement[]:[]);setInstallationRequests(Array.isArray(d.installationRequests)?d.installationRequests as InstallationRequest[]:[]);setTechnicians(Array.isArray(d.technicians)?d.technicians as Technician[]:[]);setEquipment(Array.isArray(d.equipment)?d.equipment as EquipmentItem[]:[]);setBankEntries(Array.isArray(d.bankEntries)?d.bankEntries as BankEntry[]:[]);setBackupText('');Alert.alert(tr('تم الاسترجاع'),tr('ترجعات البيانات بنجاح.'));}catch(e){Alert.alert(tr('تعذر الاسترجاع'),e instanceof Error?e.message:'النسخة غير صالحة.');}finally{setBackupBusy(false);}}}]);};
  const exportPdf=async(title:string,customerName:string,lines:string[],total:number)=>{
    try{
      const html=buildPdfHtml({language,profile:companyProfile,title,customerName,lines,total,date:new Date().toLocaleDateString(language==='AR'?'ar-MA':'fr-MA')});
      const file=await Print.printToFileAsync({html});
      if(await Sharing.isAvailableAsync()) await Sharing.shareAsync(file.uri,{mimeType:'application/pdf',dialogTitle:title});
      else Alert.alert(tr('PDF جاهز'),file.uri);
    }catch(e){Alert.alert(tr('خطأ'),tr('تعذر إنشاء PDF. تأكد من تثبيت مكتبات expo-print و expo-sharing.'));}
  };
  const checkoutPos=(data:{customerName:string;lines:{productId:number;name:string;quantity:number;unitPrice:number;discount:number}[];paymentMethod:'cash'|'card'|'transfer';total:number})=>{
    const invalid=data.lines.find(line=>{const product=products.find(p=>p.id===line.productId);return !product||warehouseStock(stockMovements,String(line.productId),activeWarehouseId)<line.quantity;});
    if(invalid){Alert.alert(tr('المخزون تبدل'),tr('الكمية المتوفرة ما بقاتش كافية. راجع السلة.'));return false;}
    const subtotal=data.lines.reduce((sum,line)=>sum+line.quantity*line.unitPrice-line.discount,0);
    const globalDiscount=Math.max(0,subtotal-data.total);
    const today=new Date().toLocaleDateString('fr-MA');
    const records=data.lines.map((line,index)=>{const raw=line.quantity*line.unitPrice-line.discount;const share=subtotal>0?globalDiscount*(raw/subtotal):0;const costPrice=products.find(p=>p.id===line.productId)?.costPrice||0;return {id:Date.now()+index,productId:line.productId,warehouseId:activeWarehouseId,productName:line.name,customerName:data.customerName,qty:line.quantity,unitPrice:line.unitPrice,costPrice,total:Math.max(0,raw-share),discount:line.discount+share,date:today,paymentMethod:data.paymentMethod};});
    if(data.paymentMethod==='cash'){try{setCashMovements(postCashMovement({id:'pos-cash-'+Date.now(),kind:'sale',amountCentimes:Math.round(data.total*100),date:new Date().toISOString().slice(0,10),note:'مبيعات نقطة البيع'},cashMovements));}catch(error){Alert.alert(tr('تعذر تسجيل حركة الصندوق'),error instanceof Error?tr(error.message):tr('راجع رصيد الصندوق.'));return false;}}setSales(current=>[...records,...current]);
    setProducts(current=>current.map(product=>{const sold=data.lines.filter(line=>line.productId===product.id).reduce((sum,line)=>sum+line.quantity,0);return sold?{...product,qty:product.qty-sold}:product;}));
    setStockMovements(current=>[...current,...data.lines.map((line,index)=>({id:'pos-'+Date.now()+'-'+index,productId:String(line.productId),warehouseId:activeWarehouseId,kind:'sale' as const,quantity:line.quantity,unitCost:products.find(p=>p.id===line.productId)?.costPrice||0,createdAt:new Date().toISOString(),note:'بيع نقطة البيع'}))]);
    const methodLabel=data.paymentMethod==='cash'?'نقداً':data.paymentMethod==='card'?'بطاقة':'تحويل';
    exportPdf('Reçu de vente',data.customerName,[...data.lines.map(line=>line.name+' × '+line.quantity+' — '+(line.quantity*line.unitPrice-line.discount).toFixed(2)+' DH'), ''+tr('طريقة الأداء:')+' '+methodLabel],data.total);
    return true;
  };
  const recordPosReturn=(sale:Sale,quantity:number,method:PosReturn['method'],reference?:string)=>{try{const result=createPosReturn(sale as PosSaleLine,posReturns,{id:'pos-return-'+Date.now(),quantity,date:new Date().toISOString().slice(0,10),method,reference});const product=products.find(item=>item.id===result.productId);if(!product)throw new Error('المنتج المرتجع غير موجود');const warehouseId=result.warehouseId;if(!warehouses.some(item=>item.id===warehouseId))throw new Error('المخزن المرتبط بالبيع غير موجود');if(method==='cash'&&result.totalCentimes>0){const nextCash=postCashMovement({id:'pos-refund-'+result.id,kind:'cash_out',amountCentimes:result.totalCentimes,date:result.date,note:'استرجاع بيع نقطة البيع '+result.id},cashMovements);setCashMovements(nextCash);}setProducts(current=>current.map(item=>item.id===result.productId?{...item,qty:item.qty+result.quantity}:item));setStockMovements(current=>[...current,{id:'return-pos-'+result.id,productId:String(result.productId),warehouseId,kind:'return_in',quantity:result.quantity,unitCost:product.costPrice||0,createdAt:new Date().toISOString(),reference:String(result.saleId),note:'إرجاع من نقطة البيع'}]);setPosReturns(current=>[result,...current]);Alert.alert(tr('تم تسجيل الإرجاع'),`${result.quantity} · ${(result.totalCentimes/100).toFixed(2)} DH`);}catch(error){Alert.alert(tr('تعذر تسجيل الإرجاع'),error instanceof Error?tr(error.message):tr('راجع الكمية والمبلغ ورصيد الصندوق.'));}};
  const go=(s:string)=>{setScreen(s);setSearch('');requestAnimationFrame(()=>mainScroll.current?.scrollTo({y:0,animated:false}));};
